"""Random valid-document generator for differential testing."""
import keyword
import random
import string

import ref as _ref

METHODS = ['GET', 'POST', 'PUT', 'HEAD', 'DELETE', 'PATCH', 'OPTIONS', "a!#$%&'*+-.^_`|~"]
TARGETS = ['/', '/alpha', '/a/b?c=d', '*', '/x%20y', '/~']
HOSTS = ['node.example', 'Node.Example', 'a.b', 'zz']


def ident(used):
    while True:
        name = random.choice(string.ascii_uppercase) + ''.join(
            random.choice(string.ascii_letters + string.digits + '_')
            for _ in range(random.randrange(0, 3)))
        if name not in used and not keyword.iskeyword(name):
            used.add(name)
            return name


def byte_literal(data):
    return 'b' + repr(data)


def definition_source(lengths, depth=0):
    existing = list(lengths)
    roll = random.random()
    if depth > 2 or roll < 0.3:
        if random.random() < 0.45:
            return byte_literal(random.choice(
                [b'x', b'abc', b'GET /a HTTP/1.1\r\n\r\n', b'AAAA', b'', b'0123456789'])
                + bytes(random.choice([0x20, 0x41, 0x0a, 0x0d, 0x30])
                        for _ in range(random.randrange(0, 3))))
        return '"%s"' % random.choice(['ok', 'ünïcode', '', 'q', 'longlong'])
    if not existing:
        return 'b"ab"'
    name = random.choice(existing)
    if roll < 0.5:
        return '(%s + %s)' % (name, definition_source(lengths, depth + 1))
    if roll < 0.7:
        return '%s * %d' % (name, random.randrange(0, 4))
    if roll < 0.78:
        return '%d * %s' % (random.randrange(0, 3), name)
    if roll < 0.92:
        high = lengths[name]
        lo = random.randrange(0, high + 1)
        hi = random.randrange(lo, high + 1)
        return '(%s)[%s:%s]' % (name, random.choice(['', str(lo)]),
                                random.choice(['', str(hi)]))
    return '(%s)[:]' % name


def payload_template(definitions):
    roll = random.random()
    if roll < 0.25 and definitions:
        return '{{ %s }}' % random.choice(definitions)
    if roll < 0.32:
        return '{{%s}}' % byte_literal(''.join(random.choice('abc/')
                                              for _ in range(4)).encode())
    if roll < 0.5:
        return ''.join(random.choice('abcXYZ:/ ') for _ in range(random.randrange(0, 6)))
    if roll < 0.7:
        parts = ['<<random_string>>' if random.random() < .5 else
                 ''.join(random.choice('abcdefgh') for _ in range(random.randrange(0, 4)))
                 for _ in range(random.randrange(1, 4))]
        return ''.join(parts)
    return ''.join(random.choice('abc') for _ in range(random.randrange(0, 5)))


def request_bytes(rng, expect=None, mode='valid'):
    if expect is None:
        method = random.choice(METHODS).encode()
        target = random.choice(TARGETS).encode()
        host = random.choice(HOSTS).encode()
    else:
        method = expect['method'].encode()
        target = expect['target'].encode()
        host = expect['host'].encode()
    if mode == 'identity-fuzzy':
        host = host.upper() if random.random() < .5 else host.lower()
        if random.random() < .3:
            host = b'other.example'
    lines = [method + b' ' + target + b' HTTP/1.1']
    if random.random() < 0.9:
        lines.append(b'Host: ' + host)
    if random.random() < 0.2:
        lines.append(b'host: ' + host)
    if random.random() < 0.4:
        lines.append(b'X-A : value ')
    if random.random() < 0.3:
        lines.append(b'X-B:\tv')
    framing = random.choice(['none', 'length', 'chunked'])
    body = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 6)))
    if random.random() < 0.15:
        body = b''
    if framing == 'length':
        values = [str(len(body))]
        if random.random() < 0.3:
            values.append('0' * random.randrange(1, 3) + str(len(body)))
        if random.random() < 0.2 and body:
            values.append(str(len(body)))
        sep = random.choice([',', ', ', ' , ', ',\t'])
        lines.append(b'Content-Length: ' + sep.join(values).encode())
        return b'\r\n'.join(lines) + b'\r\n' + body
    if framing == 'chunked':
        lines.append(b'Transfer-Encoding: ' +
                     random.choice([b'chunked', b'Chunked', b' CHUNKED ']))
        blob = b'\r\n'.join(lines) + b'\r\n'
        pieces = [body[:len(body) // 2], body[len(body) // 2:]] \
            if (body and random.random() < .5) else ([body] if body else [])
        chunks = b''
        for piece in pieces:
            if not piece:
                continue
            size = format(len(piece), 'x' if random.random() < .5 else 'X')
            if random.random() < .3:
                size = '00' + size
            suffix = b';ok=1' if random.random() < .3 else b''
            chunks += size.encode() + suffix + b'\r\n' + piece + b'\r\n'
        trailers = b'T: v\r\n' if random.random() < 0.3 else b''
        return blob + chunks + b'0\r\n' + trailers + b'\r\n'
    lines.append(b'')
    return b'\r\n'.join(lines) + b'\r\n'


def broken_blob(rng):
    return [
        b'GET / HTTP/1.1\n\n',
        b'GET / HTTP/1.0\r\n\r\n',
        b'GET  / HTTP/1.1\r\n\r\n',
        b'GE T / HTTP/1.1\r\n\r\n',
        b'GET /\r\n\r\n',
        b'GET / HTTP/1.1\r\nBad Header\r\n\r\n',
        b'GET / HTTP/1.1\r\nHo st: x\r\n\r\n',
        b'GET / HTTP/1.1\r\nX: \x01\r\n\r\n',
        b'GET / HTTP/1.1\r\nContent-Length: 5, 6\r\n\r\n',
        b'GET / HTTP/1.1\r\nContent-Length:\r\n\r\n',
        b'GET / HTTP/1.1\r\nTransfer-Encoding: gzip\r\n\r\n',
        b'GET / HTTP/1.1\r\nTransfer-Encoding: chunked\r\nContent-Length: 0\r\n\r\n',
        b'GET / HTTP/1.1\r\nTransfer-Encoding: chunked\r\nTransfer-Encoding: chunked\r\n\r\n',
        b'GET / HTTP/1.1\r\n\r\n0\r\nZ\r\n\r\n',
        b'GET / HTTP/1.1\r\n\r\nzz\r\n\r\n',
        b'GET / HTTP/1.1\r\n\r\n3\r\nabc\r\n',
        b'GET / HTTP/1.1\r\n\r\n1\r\naX\r\n\r\n',
    ][rng.randrange(17)]


def as_template(blob):
    if all(32 <= c < 127 for c in blob):
        return blob.decode('ascii')
    return '{{b"%s"}}' % ''.join('\\x%02x' % c for c in blob)


def document(rng):
    names = []
    for _ in range(rng.randrange(0, 4)):
        name = ''.join(rng.choice(string.ascii_lowercase) for _ in range(4))
        if name not in names:
            names.append(name)
    definitions = []
    defined = set()
    env = {}
    for _ in range(rng.randrange(0, 4)):
        name = ident(defined)
        lengths = {key: len(value) for key, value in env.items()}
        source = definition_source(lengths)
        definitions.append([name, source])
        env[name] = _ref.evaluate(source, env)
    defined = list(env)

    cases = []
    for name in names:
        frames = []
        for _ in range(rng.randrange(0, 4)):
            kind = rng.choice(['headers', 'headers', 'data', 'datagram', 'sleep'])
            if kind == 'sleep':
                frames.append({'Type': 'sleep', 'Time_to_Stop': rng.randrange(0, 12)})
            elif kind == 'headers':
                rows = [[payload_template(defined), payload_template(defined)]
                        for _ in range(rng.randrange(0, 4))]
                if rng.random() < 0.5 and len({row[0] for row in rows}) == len(rows):
                    frame = {'Type': 'headers',
                             'headers_kv': {row[0]: row[1] for row in rows}}
                else:
                    frame = {'Type': 'headers', 'data_to_transfered': rows}
                if rng.random() < 0.7:
                    frame['End_Stream'] = rng.random() < 0.6
                frames.append(frame)
            else:
                frame = {'Type': kind,
                         'data_to_transfered': payload_template(defined)}
                if rng.random() < 0.7:
                    frame['End_Stream'] = rng.random() < 0.6
                frames.append(frame)
        expect = {'method': rng.choice(METHODS), 'target': rng.choice(TARGETS),
                  'host': rng.choice(HOSTS)}
        cases.append({'name': name, 'frames': frames, 'expect': expect})

    timeout = rng.randrange(1, 30)
    events = []
    for _ in range(rng.randrange(0, 6)):
        kind = rng.choice(['headers', 'headers', 'data', 'close'])
        at = rng.randrange(0, 25)
        if kind == 'close':
            events.append({'at': at, 'kind': 'close'})
            continue
        stream = rng.choice([4 * i for i in range(len(cases))] + [99, 4])
        row = {'at': at, 'kind': kind, 'stream': stream, 'end': rng.random() < 0.5}
        if kind == 'headers':
            row['fields'] = [[payload_template(defined), payload_template(defined)]
                             for _ in range(rng.randrange(0, 3))]
        else:
            row['data'] = payload_template(defined)
        events.append(row)

    channels = []
    for _ in range(rng.randrange(0, 3)):
        parts = []
        for _ in range(rng.randrange(0, 4)):
            owner = rng.choice([None] + names)
            if rng.random() < 0.25:
                blob = broken_blob(rng)
            else:
                expect = None
                if owner is not None and rng.random() < 0.7:
                    for case in cases:
                        if case['name'] == owner:
                            expect = case['expect']
                blob = request_bytes(rng, expect,
                                     'identity-fuzzy' if expect and rng.random() < .4 else 'valid')
            if rng.random() < 0.2 and blob:
                blob = blob[:rng.randrange(0, len(blob))]
            parts.append({'case': owner, 'data': as_template(blob)})
        channels.append({'name': ''.join(rng.choice(string.ascii_lowercase)
                                         for _ in range(4)), 'parts': parts})
    return {'seed': ''.join(rng.choice(string.ascii_letters + '._-')
                            for _ in range(rng.randrange(0, 8))),
            'definitions': definitions, 'timeout_ms': timeout, 'cases': cases,
            'events': events, 'channels': channels}
